-- Hermes Skill 批量导入 (258个)

ON CONFLICT (slug) DO NOTHING;

-- 批量补充评测
SELECT s.id, s.tagline, 3, '基于公开信息评估', 3, '基于公开信息评估', '免费开源', '本地运行无额外成本', 3.0, 'AI360自动评测', 'ai_generated', '2026-08', NOW()
FROM skills s WHERE s.platform_id=(SELECT id FROM platforms WHERE slug='hermes') AND s.id NOT IN (SELECT DISTINCT skill_id FROM evaluations)
ON CONFLICT DO NOTHING;

UPDATE platforms SET skill_count=(SELECT count(*) FROM skills WHERE platform_id=platforms.id AND status='published') WHERE slug='hermes';